import{_ as t,o,c as a,a6 as r}from"./chunks/framework.DtfPIzdJ.js";const p=JSON.parse('{"title":"Security","description":"","frontmatter":{},"headers":[],"relativePath":"guide/security.md","filePath":"guide/security.md"}'),d={name:"guide/security.md"};function s(i,e,n,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h1><p>Cluub blocks several classes of mistakes before your code runs, through compile-time rules, generated validation and safe UI rendering, and its server ships with sensible HTTP defaults. Other protections a production web app needs are <strong>not built yet</strong>. This page lists both, checked against the 0.1 source code and by sending real requests to a running server, with mitigations for each gap. If you only read one section, read <a href="#what-is-not-there-yet">What is not there yet</a>.</p><h2 id="what-is-protected-today" tabindex="-1">What is protected today <a class="header-anchor" href="#what-is-protected-today" aria-label="Permalink to &quot;What is protected today&quot;">​</a></h2><h3 id="text-is-rendered-as-text-never-as-html" tabindex="-1">Text is rendered as text, never as HTML <a class="header-anchor" href="#text-is-rendered-as-text-never-as-html" aria-label="Permalink to &quot;Text is rendered as text, never as HTML&quot;">​</a></h3><p>Every value a view shows, such as <code>text todo.title</code>, <code>heading &quot;Hi {name}&quot;</code> or a button label, becomes a DOM <strong>text node</strong> (<code>document.createTextNode</code>). The UI runtime never uses <code>innerHTML</code>, and the language has no element that renders raw HTML. A todo titled <code>&lt;img src=x onerror=alert(1)&gt;</code> shows up as those characters on screen.</p><p>Attributes such as <code>placeholder</code>, <code>alt</code>, <code>class</code> and <code>aria-label</code> are set with <code>setAttribute</code>, and event handlers are only ever functions generated by the compiler, never strings from data.</p><h3 id="javascript-urls-are-neutralized" tabindex="-1"><code>javascript:</code> URLs are neutralized <a class="header-anchor" href="#javascript-urls-are-neutralized" aria-label="Permalink to &quot;`javascript:` URLs are neutralized&quot;">​</a></h3><p>For the <code>href</code> of <code>link ... to</code> and the <code>src</code> of <code>image</code>, the runtime replaces any value that starts with <code>javascript:</code> (ignoring case and leading spaces) with <code>#</code>. So <code>link &quot;Website&quot; to user.website</code> can&#39;t run script even when <code>website</code> came from a user. The page&#39;s Content-Security-Policy (below) blocks inline script as a second line of defense.</p><h3 id="secrets-stay-on-the-server" tabindex="-1">Secrets stay on the server <a class="header-anchor" href="#secrets-stay-on-the-server" aria-label="Permalink to &quot;Secrets stay on the server&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rule</th><th>What it stops</th></tr></thead><tbody><tr><td><strong>E204</strong></td><td><code>ask ai</code> in a page, component or layout. AI calls are only allowed in services, apis and clients, so provider keys never ship to the browser</td></tr><tr><td><strong>E205</strong></td><td>reading <code>env.NAME</code> in the UI layer</td></tr><tr><td><strong>E401</strong></td><td>text that looks like a key, written in code: <code>sk-ant-…</code>, <code>sk-…</code> (20+ chars), <code>AIza…</code>, <code>ghp_…</code>, <code>xoxb-</code>/<code>xoxp-…</code></td></tr><tr><td>Layer rules <strong>E201</strong></td><td>a page using a store, client or service directly. Pages reach data only through an <code>api</code></td></tr></tbody></table><p>The browser bundle (<code>dist/public/</code>) contains only models, pages, components, layouts and the <em>shape</em> of your api routes. Service code, store file paths, client base URLs and headers exist only in <code>dist/server.js</code>, outside the public folder.</p><p>E401 only recognizes those five patterns, and only in text literals. A password or an AWS key typed into a string isn&#39;t detected. Nothing stops an api from <em>returning</em> a secret either (<code>return env.SECRET</code>), so review what your apis send back.</p><h3 id="ai-keys-are-never-stored-by-cluub" tabindex="-1">AI keys are never stored by Cluub <a class="header-anchor" href="#ai-keys-are-never-stored-by-cluub" aria-label="Permalink to &quot;AI keys are never stored by Cluub&quot;">​</a></h3><p>Cluub never ships, proxies or stores AI keys. Developer keys live in <code>.env</code> (written with mode 600 and git-ignored by <code>cluub ai set</code>) or in real environment variables. With <code>aiKeys &quot;user&quot;</code> or <code>&quot;either&quot;</code>, an end user&#39;s key stays in their browser and reaches your server only in the <code>X-Cluub-AI-Provider</code> / <code>X-Cluub-AI-Key</code> headers of their own requests. The server scopes it to that request with <code>AsyncLocalStorage</code>, never writes it to disk or to the log, and never echoes it back. Serve such apps over HTTPS and don&#39;t log request headers in proxies. Full details: <a href="/home/guide/ai-keys">Your own AI keys</a>.</p><h3 id="input-is-validated-at-the-api-boundary" tabindex="-1">Input is validated at the api boundary <a class="header-anchor" href="#input-is-validated-at-the-api-boundary" aria-label="Permalink to &quot;Input is validated at the api boundary&quot;">​</a></h3><p>Before your route code runs, the dispatcher checks every declared parameter (path, query string or JSON body) against its type: <code>text</code>, <code>number</code>, <code>bool</code>, <code>email</code>, <code>url</code>, <code>date</code>, <code>list of T</code>, or a model. A missing value gives <code>400</code> with <code>Missing required value &quot;title&quot;</code>. A wrong type gives <code>400</code> with the field name, for example <code>total must be a number (got &quot;abc&quot;)</code>. Body fields you didn&#39;t declare are ignored, not passed through.</p><p>Creating a model validates every rule (<code>required</code>, <code>min</code>, <code>max</code>, <code>one of</code>, <code>email</code>, <code>url</code>, <code>date</code>) and <strong>rejects unknown fields</strong> (<code>Todo has no field &quot;isAdmin&quot;</code>). Stores re-validate on <code>add</code> and <code>update</code>, so a request can&#39;t sneak extra properties into stored data.</p><h3 id="http-defaults" tabindex="-1">HTTP defaults <a class="header-anchor" href="#http-defaults" aria-label="Permalink to &quot;HTTP defaults&quot;">​</a></h3><p>We verified each of these with <code>curl</code> against <code>cluub start</code>:</p><table tabindex="0"><thead><tr><th>Behavior</th><th>Response</th></tr></thead><tbody><tr><td>Body larger than 1,000,000 bytes</td><td><code>413 too_large</code>, and the connection is closed</td></tr><tr><td>Body without <code>Content-Type: application/json</code> (for example <code>text/plain</code>)</td><td><code>415 bad_content_type</code></td></tr><tr><td>Body that isn&#39;t valid JSON</td><td><code>400 bad_json</code></td></tr><tr><td>Malformed percent-encoding in the URL (<code>/%E0%A4%A</code>)</td><td><code>400 bad_url</code></td></tr><tr><td>Wrong method on a known path</td><td><code>405</code>, naming the allowed methods (<code>Use GET or POST.</code>)</td></tr><tr><td>Every response</td><td><code>X-Content-Type-Options: nosniff</code>, <code>Referrer-Policy: same-origin</code>, <code>X-Frame-Options: DENY</code></td></tr><tr><td>HTML pages</td><td><code>Content-Security-Policy: default-src &#39;self&#39;; img-src &#39;self&#39; data: https:; style-src &#39;self&#39;; script-src &#39;self&#39;; connect-src &#39;self&#39;; frame-ancestors &#39;none&#39;; base-uri &#39;self&#39;; form-action &#39;self&#39;</code></td></tr><tr><td>Static file paths</td><td>normalized, and they must stay inside <code>dist/public</code> (otherwise <code>403</code>)</td></tr><tr><td><code>.clb</code> sources, <code>.env</code>, <code>dist/server.js</code>, <code>storage/</code></td><td>never served</td></tr></tbody></table><p>Bodies are read as bytes and decoded once, so non-ASCII text (<code>café crème</code>) arrives intact. The JSON-only rule matters for CSRF: a browser can&#39;t send <code>Content-Type: application/json</code> to another site without a CORS preflight, which the server never approves. So a hostile page can&#39;t trigger your POST, PUT, PATCH or DELETE routes with a form or a simple <code>fetch</code>. The CSP has no <code>&#39;unsafe-inline&#39;</code>. The app boots from <code>/_cluub/boot.js</code>, and we confirmed in a browser that pages render under this policy with no console errors.</p><h3 id="error-messages-don-t-leak-internals-in-production" tabindex="-1">Error messages don&#39;t leak internals in production <a class="header-anchor" href="#error-messages-don-t-leak-internals-in-production" aria-label="Permalink to &quot;Error messages don&#39;t leak internals in production&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Error</th><th>Status</th><th>Message sent to the client</th></tr></thead><tbody><tr><td>Validation, <code>require</code></td><td>400</td><td>your message or the rule&#39;s message</td></tr><tr><td><code>fail &quot;...&quot;</code></td><td>400 or the status you gave, <strong>any</strong> status</td><td>your message, always</td></tr><tr><td><code>Store.get</code> on a missing id</td><td>404</td><td><code>Todo &quot;17&quot; was not found</code></td></tr><tr><td>AI failure</td><td>502</td><td><code>cluub start</code>: <code>The AI service is not available right now. Please try again.</code> · <code>cluub dev</code>: the real reason</td></tr><tr><td><code>client</code> (outside API) failure</td><td>502</td><td><code>cluub start</code>: <code>An outside service is not available right now. Please try again.</code> · <code>cluub dev</code>: the real reason</td></tr><tr><td>Any other exception (a bug)</td><td>500</td><td><code>cluub start</code>: <code>Something went wrong on the server.</code> · <code>cluub dev</code>: <code>Unexpected error in TodoApi.add: &lt;message&gt;</code></td></tr></tbody></table><p>The full error is always printed in the server log, for example <code>✗ TodoApi.summary: No API key for claude. Add ANTHROPIC_API_KEY=... to your .env file</code>. Under <code>cluub dev</code>, the first stack lines are printed too. Messages you write with <code>fail</code> are meant for users, so they&#39;re always shown. Don&#39;t put internal details in them.</p><h3 id="file-stores-write-atomically-and-load-safely" tabindex="-1">File stores write atomically and load safely <a class="header-anchor" href="#file-stores-write-atomically-and-load-safely" aria-label="Permalink to &quot;File stores write atomically and load safely&quot;">​</a></h3><p>A store saved to JSON writes a temporary file and renames it over the real one, so a crash or power loss mid-write never leaves a half-written file. Stores load when the server starts, every record is validated against the model, and a broken file stops startup with a clear message instead of serving bad data.</p><h2 id="what-is-not-there-yet" tabindex="-1">What is not there yet <a class="header-anchor" href="#what-is-not-there-yet" aria-label="Permalink to &quot;What is not there yet&quot;">​</a></h2><p>Here is what Cluub 0.1 does <strong>not</strong> do, and what to do instead.</p><h3 id="no-authentication-sessions-or-roles" tabindex="-1">No authentication, sessions or roles <a class="header-anchor" href="#no-authentication-sessions-or-roles" aria-label="Permalink to &quot;No authentication, sessions or roles&quot;">​</a></h3><p>Every api route is public. There is no login, session cookie, token check or <code>for role &quot;admin&quot;</code> (auth is on the <a href="/home/reference/roadmap">roadmap</a>).</p><p><strong>Mitigation:</strong> only deploy apps that are fine being public, or put authentication in front of the whole app: HTTP basic auth or an SSO proxy (oauth2-proxy, Cloudflare Access, a VPN) in your reverse proxy. Apis can&#39;t read cookies or headers today, so don&#39;t try to build password checks in Cluub code.</p><h3 id="no-rate-limiting" tabindex="-1">No rate limiting <a class="header-anchor" href="#no-rate-limiting" aria-label="Permalink to &quot;No rate limiting&quot;">​</a></h3><p>Nothing limits how often a client calls an api. This matters most for routes that call an AI provider, because every request costs money.</p><p><strong>Mitigation:</strong> rate-limit in the proxy (the <a href="/home/guide/deployment#behind-a-reverse-proxy-nginx">nginx example</a> does), set spending limits with your AI provider, and put <code>require text.count &lt;= N</code> on prompt inputs (the <code>ai-chat</code> template does).</p><h3 id="no-cors-configuration" tabindex="-1">No CORS configuration <a class="header-anchor" href="#no-cors-configuration" aria-label="Permalink to &quot;No CORS configuration&quot;">​</a></h3><p>The server sends no <code>Access-Control-Allow-*</code> headers. Browsers block other origins from calling or reading your api, which is the safe default and part of the CSRF protection above. You can&#39;t open the api to another frontend without a proxy that adds the headers, and adding them weakens that protection.</p><h3 id="no-https-termination" tabindex="-1">No HTTPS termination <a class="header-anchor" href="#no-https-termination" aria-label="Permalink to &quot;No HTTPS termination&quot;">​</a></h3><p>The server speaks plain HTTP.</p><p><strong>Mitigation:</strong> terminate TLS in a reverse proxy or your platform, and add <code>Strict-Transport-Security</code> there once HTTPS works.</p><h3 id="dev-mode-shows-error-details-and-listens-on-every-interface" tabindex="-1">Dev mode shows error details and listens on every interface <a class="header-anchor" href="#dev-mode-shows-error-details-and-listens-on-every-interface" aria-label="Permalink to &quot;Dev mode shows error details and listens on every interface&quot;">​</a></h3><p><code>cluub dev</code> sends real error messages (including AI and outside-API details) to the browser and, like <code>cluub start</code>, binds to all network interfaces. Anyone on the same network can reach a dev server.</p><p><strong>Mitigation:</strong> never expose <code>cluub dev</code> publicly. Use <code>cluub build</code> + <code>cluub start</code> (or <code>node dist/start.mjs</code>) for anything shared.</p><h3 id="types-are-only-enforced-at-boundaries" tabindex="-1">Types are only enforced at boundaries <a class="header-anchor" href="#types-are-only-enforced-at-boundaries" aria-label="Permalink to &quot;Types are only enforced at boundaries&quot;">​</a></h3><p>Values are checked when a model is created, when an api receives parameters and when a store saves. Return types (<code>-&gt; Todo</code>), page state and component properties aren&#39;t checked, so a service can return the wrong shape without an error. Write service and api tests for important responses (<a href="/home/guide/testing-strategy">Testing strategy</a>).</p><h3 id="other-things-to-know" tabindex="-1">Other things to know <a class="header-anchor" href="#other-things-to-know" aria-label="Permalink to &quot;Other things to know&quot;">​</a></h3><ul><li><strong>AI prompt injection.</strong> User text you interpolate into a prompt can try to steer the model. Prefer <code>as Model</code> or <code>as one of [...]</code>: the reply is validated against your model or list, so a manipulated answer still has to fit the shape.</li><li><strong><code>cluub make</code> sends your code to the AI provider:</strong> every <code>.clb</code> file in the project plus <code>LANGUAGE.md</code>. It doesn&#39;t send <code>.env</code>. Files are written only when the result compiles, only <code>.clb</code> files, and never paths containing <code>..</code> or absolute paths.</li><li><strong>Crashes.</strong> The server has no automatic restart. Run it under a supervisor (systemd <code>Restart=always</code>, Docker <code>--restart</code>).</li><li><strong>No dependency risk:</strong> Cluub and its output have zero npm dependencies, so there is no third-party supply chain to audit.</li></ul><h2 id="checklist-before-going-live" tabindex="-1">Checklist before going live <a class="header-anchor" href="#checklist-before-going-live" aria-label="Permalink to &quot;Checklist before going live&quot;">​</a></h2><ol><li><code>cluub build</code>, then <code>cluub start</code> or <code>node dist/start.mjs</code>. Never <code>cluub dev</code>.</li><li>TLS, gzip and rate limiting in a reverse proxy.</li><li>Authentication in front of the app if the data isn&#39;t public.</li><li>Secrets in environment variables (they override <code>.env</code>). Never commit <code>.env</code>; it&#39;s in <code>.gitignore</code> by default.</li><li>A supervisor that restarts the process.</li><li>Backups of <code>storage/</code>.</li><li>Review what each api returns and what each <code>fail</code> message says. Both reach the browser.</li></ol><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/home/guide/deployment">Deployment</a></li><li><a href="/home/guide/structure">Project structure &amp; layers</a></li><li><a href="/home/guide/ai">AI</a></li><li><a href="/home/reference/errors">Error codes</a></li><li><a href="/home/reference/roadmap">Status &amp; roadmap</a></li></ul>',50)])])}const y=t(d,[["render",s]]);export{p as __pageData,y as default};
